package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Whitelist;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen1Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(Whitelist.none());
    }

    @Test
    public void testIsValid_NullDocument() {
        try {
            cleaner.isValid(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected exception
        }
    }

    @Test
    public void testIsValid_EmptyDocument() {
        Document emptyDocument = Jsoup.parse("");
        assertTrue(cleaner.isValid(emptyDocument));
    }

    @Test
    public void testIsValid_SafeDocument() {
        Document safeDocument = Jsoup.parse("<p>Hello</p>");
        assertTrue(cleaner.isValid(safeDocument));
    }

    @Test
    public void testIsValid_DirtyDocumentWithUnsafeTags() {
        Document dirtyDocument = Jsoup.parse("<script>alert('XSS')</script><p>Hello</p>");
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_DirtyDocumentWithUnsafeAttributes() {
        Document dirtyDocument = Jsoup.parse("<a href='javascript:alert(\"XSS\")'>Link</a>");
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_DirtyDocumentWithMixedContent() {
        Document dirtyDocument = Jsoup.parse("<p>Safe</p><script>alert('XSS')</script>");
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testIsValid_DocumentWithOnlyWhitespace() {
        Document whitespaceDocument = Jsoup.parse("   \n\t ");
        assertTrue(cleaner.isValid(whitespaceDocument));
    }

    @Test
    public void testIsValid_DocumentWithOnlyComments() {
        Document commentDocument = Jsoup.parse("<!DOCTYPE html><!-- Comment --><p>Safe</p>");
        assertTrue(cleaner.isValid(commentDocument));
    }

    @Test
    public void testIsValid_DocumentWithOnlyDoctype() {
        Document doctypeDocument = Jsoup.parse("<!DOCTYPE html>");
        assertTrue(cleaner.isValid(doctypeDocument));
    }

    @Test
    public void testIsValid_DocumentWithNestedElements() {
        Document nestedDocument = Jsoup.parse("<div><p>Nested</p></div>");
        assertTrue(cleaner.isValid(nestedDocument));
    }
}
